    new THREE.BoxGeometry(48, 2, 48),
    concreteMat
);
base.position.y = 1;
group.add(base);

// Main tower sections - creating the stepped design
const towerSections = [
    { width: 40, height: 40, depth: 40, y: 22 },
    { width: 30, height: 60, depth: 30, y: 72 },
    { width: 20, height: 80, depth: 20, y: 152 },
    { width: 10, height: 60, depth: 10, y: 222 }
];

towerSections.forEach(section => {
    // Concrete structure
    const structure = new THREE.Mesh(
        new THREE.BoxGeometry(section.width, section.height, section.depth),
        concreteMat
    );
    structure.position.y = section.y;
    group.add(structure);

    // Glass panels on all sides
    const glassThickness = 0.5;
    const glassOffset = section.width/2 + glassThickness/2;

    // Front glass
    const frontGlass = new THREE.Mesh(
        new THREE.BoxGeometry(section.width + 2, section.height - 2, glassThickness),
        glassMat
    );
    frontGlass.position.set(0, section.y, glassOffset);
    group.add(frontGlass);

    // Back glass
    const backGlass = frontGlass.clone();
    backGlass.position.z = -glassOffset;
    group.add(backGlass);

    // Left glass
    const leftGlass = new THREE.Mesh(
        new THREE.BoxGeometry(glassThickness, section.height - 2, section.depth + 2),
        glassMat
    );
    leftGlass.position.set(-glassOffset, section.y, 0);
    group.add(leftGlass);

    // Right glass
    const rightGlass = leftGlass.clone();
    rightGlass.position.x = glassOffset;
    group.add(rightGlass);
