// Vertical window columns
const windowColumnWidth = 1.5;
const windowColumnDepth = 0.5;
const windowColumnHeight = mainTowerHeight * 0.85;

for (let i = -1; i <= 1; i++) {
    const columnX = i * (mainTowerWidth / 3);
    for (let z = -1; z <= 1; z += 2) {
        const columnZ = z * (mainTowerDepth / 2 - windowColumnDepth / 2);

        const columnGeo = new THREE.BoxGeometry(windowColumnWidth, windowColumnHeight, windowColumnDepth);
        const column = new THREE.Mesh(columnGeo, steelMat);
        column.position.set(columnX, windowColumnHeight / 2 + mainTowerHeight * 0.075, columnZ);
        group.add(column);
    }
}

// Window panels between columns
const windowPanelWidth = (mainTowerWidth / 3) - windowColumnWidth - 0.2;
const windowPanelHeight = windowColumnHeight / 15;
const windowPanelDepth = 0.2;

for (let i = 0; i < 3; i++) {
    const columnX = (i - 1) * (mainTowerWidth / 3);
    for (let z = -1; z <= 1; z += 2) {
        const columnZ = z * (mainTowerDepth / 2 + 0.1);

        for (let j = 0; j < 15; j++) {
            const windowY = j * windowColumnHeight / 15 + mainTowerHeight * 0.075;

            const panelGeo = new THREE.BoxGeometry(windowPanelWidth, windowPanelHeight, windowPanelDepth);
            const panel = new THREE.Mesh(panelGeo, glassMat);
            panel.position.set(columnX + (mainTowerWidth / 6) - (mainTowerWidth / 3 / 2), windowY + windowPanelHeight / 2, columnZ);
            group.add(panel);
        }
    }
}

