// Curved tail using a series of cylinders/spheres along a path
const tailSegments = 20;
const tailRadius = 1.2;
for (let i = 0; i < tailSegments; i++) {
  const t = i / (tailSegments - 1);
  // S-curve path for the tail
  const tx = 10 + Math.sin(t * Math.PI * 1.2) * 3;
  const ty = t * 18;
  const tz = 3 + Math.cos(t * Math.PI * 0.5) * 2;

  const segGeo = new THREE.SphereGeometry(tailRadius * (1 - t * 0.3), 10, 8);
  const seg = new THREE.Mesh(segGeo, copperMat);
  seg.position.set(tx, ty, tz);
  group.add(seg);
}

// Tail connecting cylinders for smoother look
for (let i = 0; i < tailSegments - 1; i++) {
  const t1 = i / (tailSegments - 1);
  const t2 = (i + 1) / (tailSegments - 1);

  const x1 = 10 + Math.sin(t1 * Math.PI * 1.2) * 3;
  const y1 = t1 * 18;
  const z1 = 3 + Math.cos(t1 * Math.PI * 0.5) * 2;

  const x2 = 10 + Math.sin(t2 * Math.PI * 1.2) * 3;
  const y2 = t2 * 18;
  const z2 = 3 + Math.cos(t2 * Math.PI * 0.5) * 2;

  const dx = x2 - x1;
  const dy = y2 - y1;
  const dz = z2 - z1;
  const len = Math.sqrt(dx * dx + dy * dy + dz * dz);

  const r = tailRadius * (1 - (t1 + t2) / 2 * 0.3);
  const cylGeo = new THREE.CylinderGeometry(r * 0.9, r * 0.9, len, 8);
  const cyl = new THREE.Mesh(cylGeo, copperMat);
  cyl.position.set((x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2);

  // Orient cylinder along the segment direction
  const dir = new THREE.Vector3(dx, dy, dz).normalize();
  const up = new THREE.Vector3(0, 1, 0);
  const quat = new THREE.Quaternion().setFromUnitVectors(up, dir);
  cyl.quaternion.copy(quat);
  group.add(cyl);
}

