    const rootShape = new THREE.Shape();
    rootShape.moveTo(0, 0);
    rootShape.quadraticCurveTo(-1.5 * (scaleX || 1), 3, -0.3, 7);
    rootShape.lineTo(0.3, 7);
    rootShape.quadraticCurveTo(1.5 * (scaleX || 1), 3, 0, 0);
    rootShape.closePath();

    const extrudeSettings = { depth: 0.6, bevelEnabled: false };
    const rootGeo = new THREE.ExtrudeGeometry(rootShape, extrudeSettings);
    const root = new THREE.Mesh(rootGeo, rootMat);
    root.position.set(x, 0, z);
    root.rotation.y = rotY;
    return root;
}

