    const angle = (i / 6) * Math.PI * 2;
    const rx = Math.cos(angle) * 1.8;
    const rz = Math.sin(angle) * 1.8;
    const root = createRoot(rx, rz, angle + Math.PI / 2, 0.8 + Math.random() * 0.4);
    group.add(root);
}

