function addBrace(x1, y1, z1, x2, y2, z2) {
    const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
    const len = Math.sqrt(dx * dx + dy * dy + dz * dz);
    const braceGeo = new THREE.BoxGeometry(0.25, len, 0.25);
    const brace = new THREE.Mesh(braceGeo, darkWoodMat);
    brace.position.set((x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2);
    brace.lookAt(x2, y2, z2);
    brace.rotateX(Math.PI / 2);
    return brace;
}

