// === STEEL FRAME COLUMNS ===
// Main vertical columns at corners and center dividers
const colSize = 0.3;
function addColumn(x, z, height, startY) {
  const geo = new THREE.BoxGeometry(colSize, height, colSize);
  const col = new THREE.Mesh(geo, steelFrameMat);
  col.position.set(x, startY + height / 2, z);
  group.add(col);
}

// Front face columns (Z = -buildingD/2)
const frontZ = -buildingD / 2;
const backZ = buildingD / 2;
const leftX = -buildingW / 2;
const rightX = buildingW / 2;
const centerX = 0;

// Corner columns full height
