  [leftX, frontZ], [rightX, frontZ],
  [leftX, backZ], [rightX, backZ],
  [centerX - 1.5, frontZ], [centerX + 1.5, frontZ],
  [centerX - 1.5, backZ], [centerX + 1.5, backZ],
];

columnPositions.forEach(([x, z]) => {
  addColumn(x, z, totalH + 0.5, 0.4);
});

// Additional intermediate columns on sides
const midZ1 = frontZ + buildingD * 0.33;
const midZ2 = frontZ + buildingD * 0.67;
[leftX, rightX].forEach(x => {
  addColumn(x, midZ1, totalH + 0.5, 0.4);
  addColumn(x, midZ2, totalH + 0.5, 0.4);
