});

// === APARTMENT UNITS (left and right per floor) ===
function addUnit(side, floor) {
  const floorY = 0.4 + floor * floorH;
  const unitW = (buildingW / 2 - 1.5) - 0.3;
  const unitCenterX = side === 'left' 
    ? leftX + (buildingW / 2 - 1.5) / 2 
    : rightX - (buildingW / 2 - 1.5) / 2;

  // Back wall with wood cladding
  const backWallGeo = new THREE.BoxGeometry(unitW, floorH - 0.5, 0.15);
  const backWall = new THREE.Mesh(backWallGeo, woodCladdingMat);
  backWall.userData.textureId = "wood-siding";
  backWall.position.set(unitCenterX, floorY + floorH / 2, backZ - 0.1);
  group.add(backWall);

  // Side wall (outer) with mixed materials
  const sideX = side === 'left' ? leftX + 0.1 : rightX - 0.1;
  const sideWallGeo = new THREE.BoxGeometry(0.15, floorH - 0.5, buildingD - 0.5);
  const sideWall = new THREE.Mesh(sideWallGeo, lightWallMat);
  sideWall.userData.textureId = "stucco-white";
  sideWall.position.set(sideX, floorY + floorH / 2, 0);
  group.add(sideWall);

  // Wood accent panels on sides
  const accentGeo = new THREE.BoxGeometry(0.18, floorH * 0.4, buildingD * 0.3);
  const accent = new THREE.Mesh(accentGeo, woodCladdingMat);
  accent.userData.textureId = "wood-siding";
  accent.position.set(sideX + (side === 'left' ? -0.02 : 0.02), floorY + floorH * 0.5, buildingD * 0.1);
  group.add(accent);

  // Front windows - large glazing
  const winW = unitW * 0.7;
  const winH = floorH * 0.55;

  // Upper window
  const winGeo = new THREE.BoxGeometry(winW, winH, 0.08);
  const win = new THREE.Mesh(winGeo, glassMat);
  win.userData.textureId = "glass-curtainwall";
  win.position.set(unitCenterX, floorY + floorH * 0.6, frontZ + 0.05);
  group.add(win);

  // Lower window (smaller)
  if (floor === 0) {
    const winGeo2 = new THREE.BoxGeometry(winW * 0.5, winH * 0.5, 0.08);
    const win2 = new THREE.Mesh(winGeo2, glassMat);
    win2.userData.textureId = "glass-curtainwall";
    win2.position.set(unitCenterX, floorY + floorH * 0.3, frontZ + 0.05);
    group.add(win2);
  }

  // Window frame
  const frameThick = 0.06;
  // Top frame
  const topFrameGeo = new THREE.BoxGeometry(winW + 0.1, frameThick, 0.12);
  const topFrame = new THREE.Mesh(topFrameGeo, steelFrameMat);
  topFrame.position.set(unitCenterX, floorY + floorH * 0.6 + winH / 2, frontZ + 0.02);
  group.add(topFrame);
  // Bottom frame
  const botFrame = new THREE.Mesh(topFrameGeo, steelFrameMat);
  botFrame.position.set(unitCenterX, floorY + floorH * 0.6 - winH / 2, frontZ + 0.02);
  group.add(botFrame);

  // Wood cladding accent below or beside windows on front
  const woodAccFrontGeo = new THREE.BoxGeometry(unitW * 0.35, floorH * 0.25, 0.1);
  const woodAccFront = new THREE.Mesh(woodAccFrontGeo, woodCladdingMat);
  woodAccFront.userData.textureId = "wood-siding";
  const accOffsetX = side === 'left' ? unitCenterX + unitW * 0.25 : unitCenterX - unitW * 0.25;
  woodAccFront.position.set(accOffsetX, floorY + floorH * 0.25, frontZ + 0.02);
  group.add(woodAccFront);

  // Rear windows (smaller)
  const rearWinGeo = new THREE.BoxGeometry(unitW * 0.4, winH * 0.6, 0.08);
  const rearWin = new THREE.Mesh(rearWinGeo, glassMat);
  rearWin.userData.textureId = "glass-curtainwall";
  rearWin.position.set(unitCenterX, floorY + floorH * 0.55, backZ - 0.05);
  group.add(rearWin);

  // Rear wood cladding panels
  const rearWoodGeo = new THREE.BoxGeometry(unitW * 0.45, floorH - 0.5, 0.1);
  const rearWood = new THREE.Mesh(rearWoodGeo, woodCladdingMat);
  rearWood.userData.textureId = "wood-siding";
  rearWood.position.set(unitCenterX + (side === 'left' ? -unitW * 0.2 : unitW * 0.2), floorY + floorH / 2, backZ - 0.02);
  group.add(rearWood);
}

// Create all 6 units
for (let f = 0; f < 3; f++) {
  addUnit('left', f);
