}

// === BALCONY RAILINGS ===
function addRailing(x, y, z, width, alongX) {
  const railH = 1.0;
  const railBarCount = Math.floor(width / 0.3);

  // Top rail
  const topRailGeo = alongX 
    ? new THREE.BoxGeometry(width, 0.05, 0.05)
    : new THREE.BoxGeometry(0.05, 0.05, width);
  const topRail = new THREE.Mesh(topRailGeo, railingMat);
  topRail.position.set(x, y + railH, z);
  group.add(topRail);

  // Mid rail
  const midRail = new THREE.Mesh(topRailGeo, railingMat);
  midRail.position.set(x, y + railH * 0.65, z);
  group.add(midRail);

  // Bottom rail
  const botRail = new THREE.Mesh(topRailGeo, railingMat);
  botRail.position.set(x, y + railH * 0.35, z);
  group.add(botRail);

  // Vertical posts at ends
  const postGeo = new THREE.BoxGeometry(0.05, railH, 0.05);
  const halfW = width / 2;
  if (alongX) {
    const p1 = new THREE.Mesh(postGeo, railingMat);
    p1.position.set(x - halfW, y + railH / 2, z);
    group.add(p1);
    const p2 = new THREE.Mesh(postGeo, railingMat);
    p2.position.set(x + halfW, y + railH / 2, z);
    group.add(p2);
  } else {
    const p1 = new THREE.Mesh(postGeo, railingMat);
    p1.position.set(x, y + railH / 2, z - halfW);
    group.add(p1);
    const p2 = new THREE.Mesh(postGeo, railingMat);
    p2.position.set(x, y + railH / 2, z + halfW);
    group.add(p2);
  }
}

// Front balcony railings for floors 1, 2
for (let f = 1; f < 3; f++) {
