// === X-BRACING on side elevations (characteristic steel structure) ===
function addXBrace(x, z, y, height, depth) {
  const diagLen = Math.sqrt(height * height + depth * depth);
  const angle = Math.atan2(height, depth);
  const barSize = 0.08;

  // Diagonal 1
  const braceGeo = new THREE.BoxGeometry(barSize, diagLen, barSize);
  const brace1 = new THREE.Mesh(braceGeo, steelFrameMat);
  brace1.position.set(x, y + height / 2, z);
  brace1.rotation.x = Math.PI / 2 - angle;
  group.add(brace1);

  // Diagonal 2
  const brace2 = new THREE.Mesh(braceGeo, steelFrameMat);
  brace2.position.set(x, y + height / 2, z);
  brace2.rotation.x = -(Math.PI / 2 - angle);
  group.add(brace2);
}

// Right side X-braces (visible in right elevation)
for (let f = 0; f < 3; f++) {
  const fy = 0.5 + f * floorH;
