const group = new THREE.Group();

// This is a house shaped like a car - a residential building (~8-10m tall) that looks like a sedan
// Based on the reference images showing a silver/grey sedan from all angles

// Materials
const bodyMat = new THREE.MeshStandardMaterial({ color: 0xc0c0c0, roughness: 0.3, metalness: 0.6, side: THREE.DoubleSide });
const darkMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.8, side: THREE.DoubleSide });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x88aacc, transparent: true, opacity: 0.4, metalness: 0.8, roughness: 0.1, side: THREE.DoubleSide });
const grilleMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.5, metalness: 0.7, side: THREE.DoubleSide });
const headlightMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffcc, emissiveIntensity: 0.3, transparent: true, opacity: 0.7, side: THREE.DoubleSide });
const taillightMat = new THREE.MeshStandardMaterial({ color: 0xff2200, emissive: 0xff0000, emissiveIntensity: 0.5, side: THREE.DoubleSide });
const wheelMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.6, metalness: 0.4, side: THREE.DoubleSide });
const rimMat = new THREE.MeshStandardMaterial({ color: 0x999999, roughness: 0.2, metalness: 0.8, side: THREE.DoubleSide });
const bumperMat = new THREE.MeshStandardMaterial({ color: 0x3a3a3a, roughness: 0.7, side: THREE.DoubleSide });
const foundationMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.8, side: THREE.DoubleSide });

// Dimensions: car-house is about 22m long (Z), 9m wide (X), 8m tall (Y)
// Car faces -Z direction (front of car at -Z)
const carLength = 22;
const carWidth = 9;
const bodyHeight = 4.5; // lower body height
const cabinHeight = 3.5; // cabin/greenhouse height
const groundClearance = 0.8;

// === MAIN BODY (lower section) ===
// Create car body profile using ExtrudeGeometry along X axis
const bodyShape = new THREE.Shape();
// Side profile of the lower body
// Start from rear bottom, go forward
bodyShape.moveTo(-carLength / 2, groundClearance); // rear bottom
bodyShape.lineTo(-carLength / 2 + 1, groundClearance - 0.3);
bodyShape.lineTo(-carLength / 2 + 2, groundClearance);
// Rear wheel arch
bodyShape.lineTo(-carLength / 2 + 2.5, groundClearance);
bodyShape.quadraticCurveTo(-carLength / 2 + 3, groundClearance + 1.5, -carLength / 2 + 4.5, groundClearance + 1.5);
bodyShape.quadraticCurveTo(-carLength / 2 + 6, groundClearance + 1.5, -carLength / 2 + 6, groundClearance);
// Bottom between wheels
bodyShape.lineTo(carLength / 2 - 6, groundClearance);
// Front wheel arch
bodyShape.quadraticCurveTo(carLength / 2 - 6, groundClearance + 1.5, carLength / 2 - 4.5, groundClearance + 1.5);
bodyShape.quadraticCurveTo(carLength / 2 - 3, groundClearance + 1.5, carLength / 2 - 2.5, groundClearance);
bodyShape.lineTo(carLength / 2 - 1, groundClearance);
bodyShape.lineTo(carLength / 2, groundClearance + 0.5);
// Front of car going up
bodyShape.lineTo(carLength / 2, bodyHeight);
// Hood line
bodyShape.lineTo(carLength / 2 - 1, bodyHeight + 0.2);
bodyShape.lineTo(carLength / 2 - 4, bodyHeight + 0.3);
// Windshield base
bodyShape.lineTo(carLength / 2 - 6, bodyHeight + 0.3);
// Windshield going up to roof
bodyShape.lineTo(carLength / 2 - 8, bodyHeight + cabinHeight);
// Roof
bodyShape.lineTo(-carLength / 2 + 7, bodyHeight + cabinHeight);
// Rear window going down
