// === WHEELS (as architectural columns/cylinders) ===
function createWheel(x, z) {
    // Tire
    const tireGeo = new THREE.CylinderGeometry(1.5, 1.5, 1.0, 24);
    const tire = new THREE.Mesh(tireGeo, wheelMat);
    tire.rotation.z = Math.PI / 2;
    tire.position.set(x, 1.5, z);
    group.add(tire);

    // Rim/hub
    const rimGeo = new THREE.CylinderGeometry(1.0, 1.0, 1.1, 6);
    const rim = new THREE.Mesh(rimGeo, rimMat);
    rim.rotation.z = Math.PI / 2;
    rim.position.set(x, 1.5, z);
    group.add(rim);

    // Hub cap center
    const hubGeo = new THREE.CylinderGeometry(0.3, 0.3, 1.2, 12);
    const hub = new THREE.Mesh(hubGeo, rimMat);
    hub.rotation.z = Math.PI / 2;
    hub.position.set(x, 1.5, z);
    group.add(hub);

    // Spokes
    for (let i = 0; i < 5; i++) {
        const angle = (i / 5) * Math.PI * 2;
        const spokeGeo = new THREE.BoxGeometry(1.15, 0.8, 0.12);
        const spoke = new THREE.Mesh(spokeGeo, rimMat);
        spoke.position.set(x, 1.5 + Math.sin(angle) * 0.5, z + Math.cos(angle) * 0.5);
        spoke.rotation.x = angle;
        // Position spokes on the outside face
        const outerX = x > 0 ? x + 0.55 : x - 0.55;
        spoke.position.set(outerX, 1.5, z);
        spoke.rotation.set(angle, 0, Math.PI / 2);
        // Recompute with proper radial positioning
        const spokeR = 0.6;
        spoke.position.set(
            x > 0 ? x + 0.55 : x - 0.55,
            1.5 + Math.sin(angle) * spokeR,
            z + Math.cos(angle) * spokeR
        );
        group.add(spoke);
    }

    // Wheel arch (fender) - curved shape over the wheel
    const archGeo = new THREE.TorusGeometry(1.7, 0.3, 8, 12, Math.PI);
    const arch = new THREE.Mesh(archGeo, bodyMat);
    arch.position.set(x > 0 ? x - 0.3 : x + 0.3, 1.5, z);
    arch.rotation.y = Math.PI / 2;
    arch.rotation.x = 0;
    // Actually place it properly
    arch.position.set(0, 1.5, z);
    arch.rotation.set(0, 0, 0);
    // Let me simplify - use a half-cylinder for the wheel arch
    const archShape2 = new THREE.Shape();
    archShape2.moveTo(-2.0, 0);
    archShape2.absarc(0, 0, 2.0, Math.PI, 0, false);
    archShape2.lineTo(2.0, 0);

    const archExtSettings = { steps: 1, depth: carWidth + 0.5, bevelEnabled: false };
    // Skip complex arch, the body already covers it
}

