// Helper function for pointed arch window
function createPointedArchWindow(width, height, depth) {
  const shape = new THREE.Shape();
  const hw = width / 2;
  const archStart = height * 0.6;
  shape.moveTo(-hw, 0);
  shape.lineTo(-hw, archStart);
  shape.quadraticCurveTo(-hw, height, 0, height);
  shape.quadraticCurveTo(hw, height, hw, archStart);
  shape.lineTo(hw, 0);
  shape.lineTo(-hw, 0);

  const extrudeSettings = { depth: depth, bevelEnabled: false };
  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

// Helper for buttress
function createButtress(width, depth, height) {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.lineTo(depth, 0);
  shape.lineTo(depth * 0.6, height);
  shape.lineTo(0, height);
  shape.lineTo(0, 0);

  const extrudeSettings = { depth: width, bevelEnabled: false };
  return new THREE.ExtrudeGeometry(shape, extrudeSettings);
}

