// ============ REAR - APSE ============
// Polygonal apse (5-sided)
const apseSegments = 5;
const apseRadius = 5;
const apseHeight = 14;
for (let i = 0; i < apseSegments; i++) {
  const angle1 = (i / apseSegments) * Math.PI - Math.PI / 2;
  const angle2 = ((i + 1) / apseSegments) * Math.PI - Math.PI / 2;

  const x1 = Math.cos(angle1) * apseRadius;
  const z1 = Math.sin(angle1) * apseRadius + 8;
  const x2 = Math.cos(angle2) * apseRadius;
  const z2 = Math.sin(angle2) * apseRadius + 8;

  const segWidth = Math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2);
  const segAngle = Math.atan2(x2 - x1, z2 - z1);

  // Apse wall panel
  const panelGeo = new THREE.BoxGeometry(segWidth, apseHeight, 0.5);
  const panel = new THREE.Mesh(panelGeo, brickMat);
  panel.position.set((x1 + x2) / 2, apseHeight / 2, (z1 + z2) / 2);
  panel.rotation.y = segAngle;
  panel.userData.textureId = "brick-red";
  group.add(panel);

  // Stone buttress at each joint
  const buttGeo = new THREE.BoxGeometry(0.6, apseHeight + 1, 1);
  const butt = new THREE.Mesh(buttGeo, stoneMat);
  butt.position.set(x1, apseHeight / 2, z1);
  butt.rotation.y = angle1;
  butt.userData.textureId = "stone-ashlar";
  group.add(butt);

  // Buttress pinnacle
  const pinGeo = new THREE.ConeGeometry(0.3, 1.5, 4);
  const pin = new THREE.Mesh(pinGeo, stoneMat);
  pin.position.set(x1, apseHeight + 1, z1);
  pin.userData.textureId = "stone-ashlar";
  group.add(pin);

  // Apse window
  const apseWinGeo = createPointedArchWindow(1.2, 3.5, 0.15);
  const apseWin = new THREE.Mesh(apseWinGeo, windowMat);
  apseWin.position.set((x1 + x2) / 2, 5, (z1 + z2) / 2 + 0.3);
  apseWin.rotation.y = segAngle;
  apseWin.userData.textureId = "glass-curtainwall";
  group.add(apseWin);

  // Rose windows in apse
  if (i === 2) {
    const apseRoseGeo = new THREE.CylinderGeometry(1.2, 1.2, 0.15, 16);
    const apseRose = new THREE.Mesh(apseRoseGeo, roseWindowMat);
    apseRose.rotation.x = Math.PI / 2;
    apseRose.position.set((x1 + x2) / 2, 10.5, (z1 + z2) / 2 + 0.3);
    apseRose.rotation.y = segAngle;
    apseRose.userData.textureId = "glass-curtainwall";
    group.add(apseRose);
  }
}

// Last buttress
const lastAngle = (apseSegments / apseSegments) * Math.PI - Math.PI / 2;
const lx = Math.cos(lastAngle) * apseRadius;
const lz = Math.sin(lastAngle) * apseRadius + 8;
const lButtGeo = new THREE.BoxGeometry(0.6, apseHeight + 1, 1);
const lButt = new THREE.Mesh(lButtGeo, stoneMat);
lButt.position.set(lx, apseHeight / 2, lz);
