const lPin = new THREE.Mesh(lPinGeo, stoneMat);
lPin.position.set(lx, apseHeight + 1, lz);
lPin.userData.textureId = "stone-ashlar";
group.add(lPin);

// Apse roof (conical)
const apseRoofGeo = new THREE.ConeGeometry(5.5, 5, apseSegments * 2);
