  );
  dRoofL.position.set(-dw / 4, dh + 0.4, 0);
  dRoofL.rotation.z = dRoofAngle;
  dRoofL.userData.textureId = "roof-tiles";
  dormerGroup.add(dRoofL);

  const dRoofR = new THREE.Mesh(
    new THREE.BoxGeometry(dRoofLen, 0.15, dd + 0.3),
    roofMat
  );
  dRoofR.position.set(dw / 4, dh + 0.4, 0);
  dRoofR.rotation.z = -dRoofAngle;
  dRoofR.userData.textureId = "roof-tiles";
  dormerGroup.add(dRoofR);

  // Dormer window
  const dWindow = new THREE.Mesh(
    new THREE.BoxGeometry(0.8, 1.2, 0.05),
    windowMat
  );
  dWindow.position.set(0, dh / 2, -dd / 2 - 0.12);
  dormerGroup.add(dWindow);

  // Window frame
  const dFrame = new THREE.Mesh(
    new THREE.BoxGeometry(0.9, 1.3, 0.08),
    windowFrameMat
  );
  dFrame.position.set(0, dh / 2, -dd / 2 - 0.1);
