// ===== ALE BARRELS =====
function createBarrel(x, y, z) {
  const bGroup = new THREE.Group();

  // Barrel body (slightly bulging via lathe)
  const points = [];
  for (let i = 0; i <= 10; i++) {
    const t = i / 10;
    const r = 0.35 + 0.08 * Math.sin(t * Math.PI);
    points.push(new THREE.Vector2(r, t * 1.0));
  }
  const barrelGeo = new THREE.LatheGeometry(points, 12);
  const barrel = new THREE.Mesh(barrelGeo, barrelMat);
  barrel.userData.textureId = "wood-siding";
  bGroup.add(barrel);

  // Barrel bands
  for (let by of [0.15, 0.5, 0.85]) {
    const band = new THREE.Mesh(
      new THREE.TorusGeometry(0.35 + 0.08 * Math.sin((by / 1.0) * Math.PI), 0.02, 6, 12),
      barrelBandMat
    );
    band.position.y = by;
    band.rotation.x = Math.PI / 2;
    bGroup.add(band);
  }

  bGroup.position.set(x, y, z);
  return bGroup;
}

