function createWoodpile(x, y, z) {
  const wpGroup = new THREE.Group();
  const logColors = [0x6B4226, 0x7B5232, 0x5C3A1E];

  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 5; col++) {
      const mat = new THREE.MeshStandardMaterial({
        color: logColors[Math.floor(Math.random() * logColors.length)],
        side: THREE.DoubleSide
      });
      const log = new THREE.Mesh(
        new THREE.CylinderGeometry(0.12, 0.12, 1.5, 6),
        mat
      );
      log.rotation.z = Math.PI / 2;
      log.position.set(
        0,
        0.12 + row * 0.24,
        col * 0.26 - 0.5
      );
      log.userData.textureId = "wood-siding";
      wpGroup.add(log);
    }
  }

  wpGroup.position.set(x, y, z);
  return wpGroup;
}

